function validate(input) {
  const [{ stores = [], inventory = [] }] = input;
  const known = new Set(), names = new Set(), ids = new Set(), products = new Set(), prices = new Set();
  for (const [id, name, location] of stores) {
    if ([id, name, location].includes(null)) return 'No value in stores may be null.';
    if (known.has(id)) return `store_id ${id} appears twice in stores.`;
    known.add(id);
    const folded = String(name).toLowerCase();
    if (names.has(folded)) return `Two stores are named ${name}.`;
    names.add(folded);
  }
  for (const [id, store, product, quantity, price] of inventory) {
    if ([id, store, product, quantity, price].includes(null)) return 'No value in inventory may be null.';
    if (ids.has(id)) return `inventory_id ${id} appears twice in inventory.`;
    ids.add(id);
    if (!known.has(store)) return `store_id ${store} is not in stores.`;
    const key = `${store}|${String(product).toLowerCase()}`;
    if (products.has(key)) return `Store ${store} lists ${product} twice.`;
    products.add(key);
    if (!(quantity >= 1)) return 'quantity must be at least 1.';
    if (!(price > 0)) return 'price must be positive.';
    if (prices.has(`${store}|${price}`)) return `Store ${store} has two products priced ${price}.`;
    prices.add(`${store}|${price}`);
  }
  return null;
}

