function generate(rand, size) {
  const small = size === 'small';
  const pick = list => list[Math.floor(rand() * list.length)];
  const shuffle = list => { const a = [...list]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; };
  const first = ['Downtown', 'Suburb', 'City', 'Corner', 'Plaza', 'Harbor', 'Market', 'Uptown', 'Village', 'Metro', 'River', 'Park', 'Central', 'Lake', 'Hill', 'Union', 'North', 'South', 'East', 'West'];
  const second = ['Tech', 'Mall', 'Center', 'Shop', 'Store', 'Outlet', 'Depot', 'Corner', 'Hub', 'Bazaar', 'Market', 'Emporium', 'Gallery', 'Mart', 'Trading', 'Goods', 'Supply', 'Square', 'Point', 'Express'];
  const names = shuffle(first.flatMap(a => second.map(b => `${a} ${b}`)));
  const locations = ['New York', 'Chicago', 'Los Angeles', 'Miami', 'Seattle', 'Boston'];
  const productPool = ['Laptop', 'Mouse', 'Keyboard', 'Monitor', 'Phone', 'Charger', 'Case', 'Headphones', 'Tablet', 'Stylus', 'Cover', 'Watch', 'Band', 'Camera', 'Lens', 'Speaker', 'Cable', 'Router', 'Printer', 'Webcam'];
  const pricePool = small ? [9.99, 19.99, 49.5, 100, 299.99, 999.99] : Array.from({ length: 60 }, (_, i) => Math.round((5 + i * 17.35) * 100) / 100);
  const quantities = small ? [1, 2, 3, 5, 6, 10, 20, 50] : null;
  const storeCount = small ? (rand() < 0.1 ? 0 : 1 + Math.floor(rand() * 3)) : 300;
  const stores = [];
  for (let i = 0; i < storeCount; i++) stores.push([i + 1, names[i], pick(locations)]);
  const inventory = [];
  const limit = small ? 8 : 2000;
  for (const [id] of stores) {
    const want = small ? 2 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 12);
    const count = Math.min(want, limit - inventory.length, productPool.length);
    const items = shuffle(productPool).slice(0, count), prices = shuffle(pricePool).slice(0, count);
    for (let j = 0; j < count; j++) inventory.push([0, id, items[j], small ? pick(quantities) : 1 + Math.floor(rand() * 120), prices[j]]);
  }
  const order = shuffle(inventory.map((_, i) => i + 1));
  inventory.forEach((row, i) => { row[0] = order[i]; });
  return [{ stores, inventory }];
}
